sql.commissionManagement.getPayrollOverrideP:
select COUNT(opru.override_plan_id)
from brs.override_plan_receiving_user opru
WHERE opru.user_id = :userId ;

sql.commissionManagement.deletePlan:
 DELETE
   FROM brs.commission_plan_user
   WHERE commission_plan_id = :planId;

 DELETE
   FROM brs.commission_plan_source_allocation
   WHERE commission_plan_id = :planId;

 DELETE
   FROM brs.commission_plan_allocation
   WHERE commission_plan_id = :planId;

  DELETE
   FROM brs.commission_plan
WHERE id = :planId;

sql.commissionPlan.getUserDateRange:

select user_id, start_date, end_date
from brs.commission_plan_user
where id = :rowId;

sql.commissions.getUserDatesOnCommissionPlan:
select user_id, start_date::date, end_date::date
from brs.commission_plan_user
where user_id in (:userIds);
